import csv
# Read stops file
stops = {}
with open('outputs/t05_clean_stops.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops[row['stop_id']] = row['stop_name']

# Read output file
with open('outputs/t09_poi_nearest_stop.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['nearest_stop_id']
        if stop_id not in stops:
            print(f'Missing stop_id: {stop_id}')
        else:
            print(f'{row[\"qid\"]} -> {stop_id}')
"
